// Group yesterday's leads by score and build one HTML email (also sent when there are none)
const leads = $input.all().map(i => i.json).filter(l => l && l.email);
const order = { hot: 0, warm: 1, cold: 2 };
leads.sort((a, b) => (order[a.score] ?? 3) - (order[b.score] ?? 3));
const count = s => leads.filter(l => l.score === s).length;
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const rows = leads.map(l => `<tr><td>${l.score === 'hot' ? '🔥 ' : ''}${esc(l.score)}</td>
  <td><b>${esc(l.name)}</b><br>${esc(l.email)}</td><td>${esc(l.service)}</td><td>${esc(l.summary)}</td></tr>`).join('');
const html = leads.length === 0
  ? '<p>No new leads in the last 24 hours. Time to do some outreach 💪</p>'
  : `<p><b>${leads.length}</b> new leads: 🔥 ${count('hot')} hot · ${count('warm')} warm · ${count('cold')} cold</p>
     <table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:14px">
     <tr style="background:#2c0a94;color:#fff"><th>Score</th><th>Lead</th><th>Service</th><th>Summary</th></tr>${rows}</table>`;
const subject = `Lead digest ${$now.toFormat('dd LLL')}: ${leads.length} new (${count('hot')} hot)`;
return [{ json: { subject, html } }];
